.btn-primary { background: #4f46e5; }
.btn-danger  { background: #dc2626; }

/* Even with class="btn-danger btn-primary",
   .btn-danger wins because it appears later in CSS. */

/* (1, 0, 0) */  #nav a { color: red; }       /* (1, 0, 1) */
/* (0, 2, 1) */  .nav .link:hover { color: blue; }
/* (0, 0, 0) */  :where(.nav .link) { color: slategray; }

a[href^="https://"]::after { content: " ↗"; }
input[type="email"]:invalid:not(:placeholder-shown) {
  border-color: #dc2626;
}
li + li { margin-top: 0.5rem; }

body {
  font-family: "Plus Jakarta Sans", sans-serif;
  color: #0f172a;
}
button, input, select, textarea {
  font: inherit;
  color: inherit;
}

*, *::before, *::after {
  box-sizing: border-box;
}
.card {
  width: 300px;
  padding: 24px;
  border: 1px solid #e2e8f0;
  /* Total rendered width stays exactly 300px */
}

.wrapper {
  display: flow-root; /* Establishes BFC without clipping overflow */
  background: #f8fafc;
}
.wrapper > h2 {
  margin-top: 32px; /* Stays cleanly inside .wrapper */
}

.container {
  inline-size: min(100% - 2rem, 72rem);
  margin-inline: auto;
  padding-block: 3rem;
  border-inline-start: 2px solid #4f46e5;
}

.video-frame {
  width: min(100%, 720px);
  aspect-ratio: 16 / 9;
  object-fit: cover;
}
.pill-tag {
  width: fit-content;
}

.hero {
  min-height: 100dvh;
}
.article-prose {
  font-size: 1rem;
  line-height: 1.65;
  max-width: 68ch;
}

h1 {
  font-size: clamp(2rem, 1.5rem + 2.5vw, 3.25rem);
  line-height: 1.15;
  text-wrap: balance;
}
.metric-value {
  font-variant-numeric: tabular-nums;
}

:root {
  --accent: oklch(54% 0.22 268);
  --accent-hover: color-mix(in oklch, var(--accent) 85%, black);
  --accent-soft: color-mix(in oklch, var(--accent) 12%, white);
}

@font-face {
  font-family: "Plus Jakarta Sans";
  src: url("/fonts/jakarta-var.woff2") format("woff2");
  font-weight: 400 800;
  font-display: swap;
}

.toolbar {
  position: sticky;
  top: 0;
  z-index: 20;
}
.avatar-wrap { position: relative; }
.avatar-badge { position: absolute; inset-block-end: 0; inset-inline-end: 0; }

.card {
  position: relative;
  isolation: isolate; /* Contains child z-indexes safely */
}
.card-bg {
  position: absolute;
  inset: 0;
  z-index: -1; /* Sits behind card text, NOT behind page body */
}

.sidebar-scroll {
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}
.navbar .cta {
  margin-inline-start: auto;
}

.layout { display: flex; gap: 2rem; }
.sidebar { flex: 0 0 260px; } /* Fixed 260px, never grows or shrinks */
.main    { flex: 1 1 0%; }   /* Consumes all remaining space */

.lesson-row { display: flex; align-items: center; gap: 0.75rem; }
.lesson-meta { flex: 1; min-width: 0; } /* Crucial! */
.lesson-title {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.filter-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
}

.course-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.5rem;
}

.catalog-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(280px, 100%), 1fr));
  gap: 1.5rem;
}

.workspace {
  display: grid;
  grid-template-columns: 260px minmax(0, 1fr);
  grid-template-areas:
    "sidebar header"
    "sidebar main";
}
.sidebar { grid-area: sidebar; }
.header  { grid-area: header; }
.main    { grid-area: main; }

.cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.5rem;
}
.card {
  display: grid;
  grid-row: span 3; /* Title, body, footer */
  grid-template-rows: subgrid;
  row-gap: 0.75rem;
}

.grid {
  display: grid;
  gap: 1.5rem;
}
@media (width >= 48rem) {
  .grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (width >= 64rem) {
  .grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}

.card-host {
  container-type: inline-size;
  container-name: card;
}
.card { display: grid; gap: 1rem; }
@container card (width >= 460px) {
  .card { grid-template-columns: 180px 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
@media (hover: hover) and (pointer: fine) {
  .card:hover { transform: translateY(-2px); }
}

@media print {
  header, nav, .no-print { display: none !important; }
  body { background: #fff; color: #000; }
  pre, .card { break-inside: avoid; }
}

.interactive-card {
  transition: transform 180ms cubic-bezier(0.16, 1, 0.3, 1),
              border-color 180ms ease-out;
}
.interactive-card:hover {
  transform: translateY(-2px);
}

.menu-panel {
  transform-origin: top right;
  scale: 0.96;
  opacity: 0;
  transition: scale 160ms ease-out, opacity 160ms ease-out;
}
.menu-panel.open {
  scale: 1;
  opacity: 1;
}

@keyframes fadeSlideUp {
  from { opacity: 0; translate: 0 12px; }
  to   { opacity: 1; translate: 0 0; }
}
.toast {
  animation: fadeSlideUp 220ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

dialog[open] {
  opacity: 1;
  scale: 1;
  transition: opacity 180ms ease-out, scale 180ms ease-out;
  @starting-style {
    opacity: 0;
    scale: 0.96;
  }
}

@layer reset, components, utilities;

@layer components {
  .card .title.highlighted { color: slategray; } /* (0,3,0) */
}
@layer utilities {
  .text-indigo { color: #4f46e5; } /* (0,1,0) STILL WINS! */
}

.field-group:has(input:focus-visible) {
  border-color: #4f46e5;
}
.card:not(:has(img)) {
  padding-block-start: 2rem;
}
body:has(dialog[open]) {
  overflow: hidden;
}

.course-card {
  padding: 1.5rem;
  border: 1px solid #e2e8f0;

  &:hover {
    border-color: #6366f1;
  }

  @media (width >= 48rem) {
    padding: 2rem;
  }
}

@scope (.lesson-prose) to (.code-block) {
  p { line-height: 1.75; color: #334155; }
  a { text-decoration: underline; }
}

:root {
  --canvas: #f8fafc;
  --surface: #ffffff;
  --ink: #0f172a;
  --accent: #4f46e5;
}
.dark {
  --canvas: #0b1120;
  --surface: #111827;
  --ink: #f8fafc;
  --accent: #6366f1;
}
body { background: var(--canvas); color: var(--ink); }

@property --ring-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}
.progress-ring {
  background: conic-gradient(#4f46e5 var(--ring-angle), #e2e8f0 0);
  transition: --ring-angle 400ms ease-out;
}

.syllabus-section {
  content-visibility: auto;
  contain-intrinsic-size: auto 380px;
}

@supports (animation-timeline: scroll()) {
  @keyframes grow-bar { from { scale: 0 1; } to { scale: 1 1; } }
  .reading-progress {
    transform-origin: left;
    animation: grow-bar linear both;
    animation-timeline: scroll(root);
  }
}

:root {
  --brand: oklch(54% 0.22 264);
  --brand-hover: color-mix(in oklch, var(--brand) 88%, black);
  --brand-soft: color-mix(in oklch, var(--brand) 14%, transparent);
}

.scroll-tabs {
  overflow-x: auto;
  mask-image: linear-gradient(to right, black 0%, black 88%, transparent 100%);
}
.avatar-hex {
  clip-path: polygon(50% 0%, 95% 25%, 95% 75%, 50% 100%, 5% 75%, 5% 25%);
}

.top-nav {
  background: color-mix(in srgb, var(--surface) 88%, transparent);
}
@supports (backdrop-filter: blur(12px)) {
  .top-nav {
    background: color-mix(in srgb, var(--surface) 72%, transparent);
    backdrop-filter: blur(12px) saturate(140%);
  }
}

h2[id], h3[id] {
  scroll-margin-top: 5.5rem;
}
.sidebar-outline {
  overflow-y: auto;
  overscroll-behavior: contain;
}
.carousel {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
}
.carousel > article { scroll-snap-align: start; }

:is(a, button, input, select, textarea, [tabindex]):focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.btn:focus:not(:focus-visible) {
  outline: none;
}

.callout {
  padding-block: 1rem;
  padding-inline: 1.25rem;
  margin-block-end: 1.5rem;
  border-inline-start: 3px solid var(--accent);
  text-align: start;
}

:root { color-scheme: light dark; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

@media (prefers-contrast: more) {
  .card { border-width: 2px; border-color: currentColor; }
}

@media print {
  nav, .sidebar, .no-print { display: none !important; }
  pre, .lesson-card { break-inside: avoid; }
  body { color: #000; background: #fff; font-size: 11pt; }
}

.long-course-section {
  content-visibility: auto;
  contain-intrinsic-size: 1px 600px;
}
